-- 0079_pops_carga_3 — carga dos POPs (041/2026 a 057/2026)
-- Origem: documentos .docx/PDF da clínica. Aditivo e idempotente:
-- regrava título/estrutura do POP de mesmo número (clinic_id, numero).

on conflict (clinic_id, numero) do update set
  titulo = excluded.titulo,
  estrutura = excluded.estrutura,
  updated_at = now();
